import yfinance as yf
import pandas as pd
import numpy as np

tickers = {'^GSPC': 'S&P 500', 'GC=F': 'Gold', 'CL=F': 'WTI Oil', '^TNX': 'US 10Y Yield', 'DX-Y.NYB': 'DXY'}
periods = [
    ('2023-10-06', '2023-11-07', 'Oct-Nov 2023'),
    ('2024-04-12', '2024-05-13', 'Apr-May 2024')
]

results = {}
for start, end, label in periods:
    data = yf.download(list(tickers.keys()), start=start, end=end)['Close']
    returns = data.pct_change().dropna()
    total_return = (data.iloc[-1] / data.iloc[0] - 1) * 100
    ann_vol = returns.std() * np.sqrt(252) * 100

    period_results = {}
    for t in tickers:
        period_results[tickers[t]] = {
            'Total Return (%)': round(total_return[t], 2),
            'Annualized Volatility (%)': round(ann_vol[t], 2)
        }
    results[label] = period_results

print(results)
